```java
class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int full = (1 << m) - 1;
        int[] dp = new int[1 << m];
        int[] gcdCache = new int[m * m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                gcdCache[i * m + j] = gcd(nums[i], nums[j]);

        for (int mask = 0; mask <= full; mask++) {
            int cnt = Integer.bitCount(mask);
            if (cnt % 2 != 0) continue;
            if (mask == full) continue;
            int op = cnt / 2 + 1;
            // pick first unused index
            int i = 0;
            while ((mask & (1 << i)) != 0) i++;
            for (int j = i + 1; j < m; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int nmask = mask | (1 << i) | (1 << j);
                dp[nmask] = Math.max(dp[nmask], dp[mask] + op * gcdCache[i * m + j]);
            }
        }
        return dp[full];
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
```

