import java.math.BigInteger;

class Solution {
    public String abbreviateProduct(int left, int right) {
        BigInteger p = BigInteger.ONE;
        long c2 = 0, c5 = 0;
        for (int i = left; i <= right; i++) {
            p = p.multiply(BigInteger.valueOf(i));
            int x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            while (x % 5 == 0) { x /= 5; c5++; }
        }
        long c = Math.min(c2, c5);
        if (c > 0) p = p.divide(BigInteger.TEN.pow((int) c));
        String s = p.toString();
        int d = s.length();
        if (d <= 10) return s + "e" + c;
        return s.substring(0, 5) + "..." + s.substring(d - 5) + "e" + c;
    }
}
```

