```java
class MKAverage {
    private static final int MAXV = 100000;
    private static final int TOP = Integer.highestOneBit(MAXV);

    private final int m;
    private final int k;
    private final int[] cntBit;
    private final long[] sumBit;
    private final int[] buffer;
    private int head;
    private int count;
    private long totalSum;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.cntBit = new int[MAXV + 1];
        this.sumBit = new long[MAXV + 1];
        this.buffer = new int[m];
    }

    public void addElement(int num) {
        if (count == m) {
            int old = buffer[head];
            update(old, -1, -old);
            totalSum -= old;
            buffer[head] = num;
            head++;
            if (head == m) {
                head = 0;
            }
        } else {
            buffer[(head + count) % m] = num;
            count++;
        }
        update(num, 1, num);
        totalSum += num;
    }

    public int calculateMKAverage() {
        if (count < m) {
            return -1;
        }
        long sumSmall = sumOfKSmallest(k);
        long sumLarge = sumOfKLargest(k);
        long midSum = totalSum - sumSmall - sumLarge;
        return (int) (midSum / (m - 2 * k));
    }

    private void update(int val, int cntDelta, long sumDelta) {
        for (int i = val; i <= MAXV; i += i & (-i)) {
            cntBit[i] += cntDelta;
            sumBit[i] += sumDelta;
        }
    }

    private int prefixCount(int val) {
        int s = 0;
        for (int i = val; i > 0; i -= i & (-i)) {
            s += cntBit[i];
        }
        return s;
    }

    private long prefixSum(int val) {
        long s = 0;
        for (int i = val; i > 0; i -= i & (-i)) {
            s += sumBit[i];
        }
        return s;
    }

    private int kthSmallest(int target) {
        int pos = 0;
        int rem = target;
        for (int pw = TOP; pw > 0; pw >>= 1) {
            int next = pos + pw;
            if (next <= MAXV && cntBit[next] < rem) {
                pos = next;
                rem -= cntBit[next];
            }
        }
        return pos + 1;
    }

    private long sumOfKSmallest(int kk) {
        int v = kthSmallest(kk);
        return prefixSum(v) - (long) (prefixCount(v) - kk) * v;
    }

    private long sumOfKLargest(int kk) {
        int v = kthSmallest(count - kk + 1);
        long suffixCnt = count - prefixCount(v - 1);
        return (totalSum - prefixSum(v - 1)) - (suffixCnt - kk) * v;
    }
}
```

