```java
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (n == 1) return true;
        if (stones[1] != 1) return false;

        // Pruning: gap between consecutive stones i-1 and i can't exceed i
        for (int i = 2; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) return false;
        }

        Map<Integer, Set<Integer>> dp = new HashMap<>();
        for (int pos : stones) {
            dp.put(pos, new HashSet<>());
        }
        dp.get(0).add(0);

        int last = stones[n - 1];
        for (int i = 0; i < n; i++) {
            int pos = stones[i];
            for (int k : dp.get(pos)) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    long target = (long) pos + step;
                    if (target > last) continue;
                    Set<Integer> set = dp.get((int) target);
                    if (set != null) {
                        set.add(step);
                    }
                }
            }
            if (i == n - 1) break; // done
        }

        return !dp.get(last).isEmpty();
    }
}
```

