class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        // rowPrefix[i][j] = sum of grid[i][0..j-1]
        long[][] rowPrefix = new long[m][n + 1];
        // colPrefix[i][j] = sum of grid[0..i-1][j]
        long[][] colPrefix = new long[m + 1][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPrefix[i][j + 1] = rowPrefix[i][j] + grid[i][j];
                colPrefix[i + 1][j] = colPrefix[i][j] + grid[i][j];
            }
        }

        int maxK = Math.min(m, n);
        for (int k = maxK; k >= 2; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    if (isMagic(grid, i, j, k, rowPrefix, colPrefix)) {
                        return k;
                    }
                }
            }
        }
        return 1;
    }

    private boolean isMagic(int[][] grid, int r, int c, int k, long[][] rowPrefix, long[][] colPrefix) {
        // target = sum of first row
        long target = rowPrefix[r][c + k] - rowPrefix[r][c];
        // check rows
        for (int i = 1; i < k; i++) {
            if (rowPrefix[r + i][c + k] - rowPrefix[r + i][c] != target) return false;
        }
        // check columns
        for (int j = 0; j < k; j++) {
            if (colPrefix[r + k][c + j] - colPrefix[r][c + j] != target) return false;
        }
        // main diagonal: (r+t, c+t) for t in 0..k-1
        long d1 = 0, d2 = 0;
        for (int t = 0; t < k; t++) {
            d1 += grid[r + t][c + t];
            d2 += grid[r + t][c + k - 1 - t];
        }
        return d1 == target && d2 == target;
    }
}
```

