class Solution {
    public String licenseKeyFormatting(String s, int k) {
        // Count alphanumeric characters
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c != '-') count++;
        }
        if (count == 0) return "";

        int first = count % k;
        if (first == 0) first = k;

        StringBuilder sb = new StringBuilder();
