        int charsInGroup = 0;
        for (char c : s.toCharArray()) {
            if (c == '-') continue;
            if (idx > 0 && charsInGroup == 0) {
                sb.append('-');
            }
            sb.append(Character.toUpperCase(c));
            idx++;
            charsInGroup++;
            if (charsInGroup == k) charsInGroup = 0;
        }
        return sb.toString();
    }
}
