class Solution {
    public int maxEqualFreq(int[] nums) {
        int[] count = new int[100001];
        int[] freq = new int[100001];
        int maxFreq = 0;
        int ans = 0;

        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            count[v]++;
            freq[count[v]]++;
            if (count[v] > 1) {
                freq[count[v] - 1]--;
            }
            if (count[v] > maxFreq) {
                maxFreq = count[v];
            }

            int n = i + 1;
            // Case 1: all values occur once -> remove any element.
            // Case 2: one value occurs once, all others occur maxFreq times
            //         -> remove that single-occurrence value.
            // Case 3: one value occurs maxFreq times, all others occur maxFreq-1 times
            //         -> remove one occurrence of the max-frequency value.
            if (maxFreq == 1
                    || maxFreq * freq[maxFreq] == n - 1
                    || (maxFreq - 1) * (freq[maxFreq - 1] + 1) == n - 1) {
                ans = n;
            }
        }

        return ans;
    }
}
```

