class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        long ans = 0, sum = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];
            while (left <= right) {
                int l = fruits[left][0], r = fruits[right][0];
                long cost = Math.min(
                    Math.abs(startPos - l) + (r - l),
                    Math.abs(startPos - r) + (r - l));
                if (cost <= k) break;
                sum -= fruits[left][1];
                left++;
            }
            ans = Math.max(ans, sum);
        }
        return (int) ans;
    }
}
```

