class Solution {
    public long maxRunTime(int n, int[] batteries) {
        long total = 0;
        for (int b : batteries) total += b;
        long lo = 0, hi = total / n;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            if (canRun(n, batteries, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }

    private boolean canRun(int n, int[] batteries, long t) {
        long need = (long) n * t;
        long have = 0;
        for (int b : batteries) {
            have += Math.min((long) b, t);
            if (have >= need) return true;
        }
        return have >= need;
    }
}
```

