        // dp
        int[] dp = new int[1 << n];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        // Actually let's do dp[i][mask] = max count for rows 0..i with row i mask.
        // Initialize row 0.
        for (int i = 0; i < m; i++) {
            int[] ndp = new int[1 << n];
            Arrays.fill(ndp, -1);
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & ~avail[i]) != 0) continue;
                if ((mask & (mask << 1)) != 0) continue; // adjacent bits
                int bits = Integer.bitCount(mask);
                if (i == 0) {
                    ndp[mask] = bits;
                } else {
                    int best = -1;
                    for (int prev = 0; prev < (1 << n); prev++) {
                        if (dp[prev] < 0) continue;
                        if ((mask & (prev << 1)) != 0) continue;
                        if ((mask & (prev >> 1)) != 0) continue;
