class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int full = 1 << n;

        int[] avail = new int[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    avail[i] |= (1 << j);
                }
            }
        }

        int[] dp = new int[full];
        for (int i = 0; i < m; i++) {
            int[] ndp = new int[full];
            for (int mask = 0; mask < full; mask++) {
                if ((mask & ~avail[i]) != 0 || (mask & (mask << 1)) != 0) {
                    ndp[mask] = -1;
                    continue;
                }
                int bits = Integer.bitCount(mask);
                if (i == 0) {
                    ndp[mask] = bits;
                } else {
                    int best = -1;
                    for (int prev = 0; prev < full; prev++) {
                        if (dp[prev] < 0) continue;
                        if ((mask & (prev << 1)) != 0 || (mask & (prev >> 1)) != 0) continue;
                        if (dp[prev] > best) best = dp[prev];
                    }
                    ndp[mask] = best >= 0 ? best + bits : -1;
                }
            }
            dp = ndp;
        }

        int ans = 0;
        for (int v : dp) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}
