class Solution {
    public int minOperations(String s) {
        int count0 = 0; // changes to make "0101..."
        for (int i = 0; i < s.length(); i++) {
            char expected = (i % 2 == 0) ? '0' : '1';
            if (s.charAt(i) != expected) count0++;
        }
        return Math.min(count0, s.length() - count0);
    }
}
