class Solution {
    public int numOfWays(int[] nums) {
        int n = nums.length;
        long MOD = 1_000_000_007L;
        // Precompute Pascal's triangle
        long[][] C = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
            }
        }
        List<Integer> list = new ArrayList<>();
        for (int x : nums) list.add(x);
        return (int) ((dfs(list, C) - 1 + MOD) % MOD);
    }

    private long dfs(List<Integer> nums, long[][] C) {
        int n = nums.size();
        if (n <= 2) return 1;
        int root = nums.get(0);
        List<Integer> left = new ArrayList<>();
        List<Integer> right = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            if (nums.get(i) < root) left.add(nums.get(i));
            else right.add(nums.get(i));
        }
        long ways = C[n-1][left.size()];
        ways = (ways * dfs(left, C)) % MOD;
        ways = (ways * dfs(right, C)) % MOD;
        return ways;
    }
}
