```java
import java.util.*;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return (int) (count(nums1, nums2) + count(nums2, nums1));
    }

    // Sum over x in a of the number of pairs (j, k), j < k, in b with b[j] * b[k] == x * x
    private long count(int[] a, int[] b) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : b) {
            freq.merge(v, 1, Integer::sum);
        }
        long total = 0;
        for (int x : a) {
            long sq = (long) x * x;
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                long v = e.getKey();
                if (sq % v != 0) {
                    continue;
                }
                long w = sq / v;
                if (w == v) {
                    long c = e.getValue();
                    total += c * (c - 1) / 2;
                } else if (w > v && w <= Integer.MAX_VALUE) {
                    Integer cw = freq.get((int) w);
                    if (cw != null) {
                        total += (long) e.getValue() * cw;
                    }
                }
            }
        }
        return total;
    }
}
```

