import java.util.Arrays;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        for (int x : nums) {
            if (x > target) return false;
        }

        int size = 1 << n;
        int[] dp = new int[size];
        Arrays.fill(dp, -1);
        dp[0] = 0;
