```java
import java.util.Arrays;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        for (int x : nums) {
            if (x > target) return false;
        }

        int full = 1 << n;
        int[] dp = new int[full];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] < 0) continue;
            int rem = dp[mask];
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int next = rem + nums[i];
                if (next > target) continue;
                int nm = mask | (1 << i);
                if (dp[nm] < 0) {
                    dp[nm] = next == target ? 0 : next;
                }
            }
        }
        return dp[full - 1] == 0;
    }
}
```

