class Solution {
    private int[] parent;
    private int[] size;

    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        boolean[] result = new boolean[requests.length];

        for (int j = 0; j < requests.length; j++) {
            int ru = find(requests[j][0]);
            int rv = find(requests[j][1]);
            if (ru == rv) {
                result[j] = true;
                continue;
            }
            boolean ok = true;
            for (int[] r : restrictions) {
                int rx = find(r[0]);
                int ry = find(r[1]);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                if (size[ru] < size[rv]) {
                    parent[ru] = rv;
                    size[rv] += size[ru];
                } else {
                    parent[rv] = ru;
                    size[ru] += size[rv];
                }
                result[j] = true;
            }
        }

        return result;
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
}
