Let me implement union-find on 3n x 3n grid.

Steps:
1. Create boolean/int array of size 3n x 3n, initialized to 0 (open).
2. For each cell (i, j):
   - if '/': mark (3i, 3j+2), (3i+1, 3j+1), (3i+2, 3j) as blocked.
   - if '\\': mark (3i, 3j), (3i+1, 3j+1), (3i+2, 3j+2) as blocked.
3. Union-find over all cells; count number of components among open cells.

Alternative: DFS flood fill counting regions. With n up to 30, 90x90 = 8100 cells, trivial.

Let me write union-find:

```java
class Solution {
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int m = 3 * n;
        int[] parent = new int[m * m];
        int[] rank = new int[m * m];
        for (int i = 0; i < parent.length; i++) parent[i] = i;

        boolean[][] blocked = new boolean[m][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == '/') {
                    blocked[3*i][3*j+2] = true;
                    blocked[3*i+1][3*j+1] = true;
                    blocked[3*i+2][3*j] = true;
                } else if (c == '\\') {
                    blocked[3*i][3*j] = true;
                    blocked[3*i+1][3*j+1] = true;
                    blocked[3*i+2][3*j+2] = true;
                }
            }
        }

        int count = 0;
        // union adjacent open cells
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < m; c++) {
                if (blocked[r][c]) continue;
                // union with right and down neighbors
                if (c + 1 < m && !blocked[r][c+1]) union(parent, rank, r*m+c, r*m+c+1);
                if (r + 1 < m && !blocked[r+1][c]) union(parent, rank, r*m+c, (r+1)*m+c);
            }
        }

        // count distinct roots among open cells
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < m; c++) {
                if (!blocked[r][c] && find(parent, r*m+c) == r*m+c) count++;
            }
        }
        return count;
    }

    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void union(int[] parent, int[] rank, int a, int b) {
        int ra = find(parent, a), rb = find(parent, b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
    }
}
```

