public List<String> removeInvalidParentheses(String s) {
    int rmL = 0, rmR = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') rmR++;
        else if (s.charAt(i) == ')') {
            if (rmR != 0) rmR--;
            else rmL++;
        }
    }
    List<String> res = new ArrayList<>();
    dfs(s, 0, res, new StringBuilder(), rmL, rmR, 0);
    return res;
}

private void dfs(String s, int i, List<String> res, StringBuilder path, int rmL, int rmR, int open) {
    if (i == s.length()) {
        if (rmL == 0 && rmR == 0 && open == 0) {
            res.add(path.toString());
        }
        return;
    }
    char c = s.charAt(i);
    int len = path.length();

    if (c == '(') {
        // remove it
        if (rmR > 0) {
            dfs(s, i + 1, res, path, rmL, rmR - 1, open);
        }
        // keep it
        path.append(c);
        dfs(s, i + 1, res, path, rmL, rmR, open + 1);
        path.setLength(len);
    } else if (c == ')') {
        if (rmL > 0) {
            dfs(s, i + 1, res, path, rmL - 1, rmR, open);
        }
        if (open > 0) {
            path.append(c);
            dfs(s, i + 1, res, path, rmL, rmR, open - 1);
            path.setLength(len);
        }
    } else {
        path.append(c);
        dfs(s, i + 1, res, path, rmL, rmR, open);
        path.setLength(len);
    }
}
