```java
class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int rmL = 0, rmR = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') rmR++;
            else if (c == ')') {
                if (rmR > 0) rmR--;
                else rmL++;
            }
        }
        List<String> res = new ArrayList<>();
        dfs(s, 0, rmL, rmR, 0, false, new StringBuilder(), res);
        return res;
    }

    private void dfs(String s, int i, int rmL, int rmR, int open, boolean prevRemoved,
                     StringBuilder path, List<String> res) {
        if (i == s.length()) {
            if (rmL == 0 && rmR == 0 && open == 0) {
                res.add(path.toString());
            }
            return;
        }
        char c = s.charAt(i);
        if (c == '(') {
            // remove
            if (rmR > 0 && (i == 0 || s.charAt(i - 1) != '(' || prevRemoved)) {
                dfs(s, i + 1, rmL, rmR - 1, open, true, path, res);
            }
            // keep
            path.append(c);
            dfs(s, i + 1, rmL, rmR, open + 1, false, path, res);
            path.deleteCharAt(path.length() - 1);
        } else if (c == ')') {
            // remove
            if (rmL > 0 && (i == 0 || s.charAt(i - 1) != ')' || prevRemoved)) {
                dfs(s, i + 1, rmL - 1, rmR, open, true, path, res);
            }
            // keep
            if (open > 0) {
                path.append(c);
                dfs(s, i + 1, rmL, rmR, open - 1, false, path, res);
                path.deleteCharAt(path.length() - 1);
            }
        } else {
            path.append(c);
            dfs(s, i + 1, rmL, rmR, open, false, path, res);
            path.deleteCharAt(path.length() - 1);
        }
    }
}
