```java
public List<String> removeInvalidParentheses(String s) {
    int l = 0, r = 0;  // l = rmL (extra ')'), r = rmR (extra '(')
    for (char c : s.toCharArray()) {
        if (c == '(') r++;
        else if (c == ')') {
            if (r > 0) r--;
            else l++;
        }
    }
    List<String> res = new ArrayList<>();
    dfs(s, 0, l, r, 0, new StringBuilder(), res);
    return res;
}

void dfs(String s, int i, int l, int r, int open, StringBuilder sb, List<String> res) {
    if (i == s.length() && l == 0 && r == 0 && open == 0) { res.add(sb.toString()); return; }
    if (i == s.length() || l < 0 || r < 0 || open < 0) return;
    char c = s.charAt(i);
    int len = sb.length();
    if (c == '(') {
        dfs(s, i + 1, l, r - 1, open, sb);      // remove
        dfs(s, i + 1, l, r, open + 1, sb.append(c)); 
    } else if (c == ')') {
        dfs(s, i + 1, l - 1, r, open, sb);      // remove
        dfs(s, i + 1, l, r, open - 1, sb.append(c));
    } else {
        dfs(s, i + 1, l, r, open, sb.append(c));
    }
    sb.setLength(len);
}
```

