```java
import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int extraClose = 0; // ')' that must be removed
        int extraOpen = 0;  // '(' that must be removed
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                extraOpen++;
            } else if (c == ')') {
                if (extraOpen > 0) extraOpen--;
                else extraClose++;
            }
        }
        List<String> result = new ArrayList<>();
        dfs(s, 0, extraClose, extraOpen, 0, false, new StringBuilder(), result);
        return result;
    }

    // prevRemovedInRun: true iff the character at index i-1 was removed
    private void dfs(String s, int i, int rmClose, int rmOpen, int open,
                     boolean prevRemoved, StringBuilder path, List<String> result) {
        if (i == s.length()) {
            if (rmClose == 0 && rmOpen == 0 && open == 0) {
                result.add(path.toString());
            }
            return;
        }
        char c = s.charAt(i);
        int len = path.length();
        if (c == '(') {
            if (rmOpen > 0 && (i == 0 || s.charAt(i - 1) != '(' || prevRemoved)) {
                dfs(s, i + 1, rmClose, rmOpen - 1, open, true, path, result);
            }
            path.append(c);
            dfs(s, i + 1, rmClose, rmOpen, open + 1, false, path, result);
            path.setLength(len);
        } else if (c == ')') {
            if (rmClose > 0 && (i == 0 || s.charAt(i - 1) != ')' || prevRemoved)) {
                dfs(s, i + 1, rmClose - 1, rmOpen, open, true, path, result);
            }
            if (open > 0) {
                path.append(c);
                dfs(s, i + 1, rmClose, rmOpen, open - 1, false, path, result);
                path.setLength(len);
            }
        } else {
            path.append(c);
            dfs(s, i + 1, rmClose, rmOpen, open, false, path, result);
            path.setLength(len);
        }
    }
}
```

