```java
import java.util.TreeMap;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] ans = new double[n - k + 1];
        TreeMap<Integer, Integer> left = new TreeMap<>();   // smaller half, max = lastKey
        TreeMap<Integer, Integer> right = new TreeMap<>();  // larger half, min = firstKey
        int[] size = new int[2]; // size[0]: left, size[1]: right

        for (int i = 0; i < k; i++) {
            add(nums[i], left, right, size);
        }
        ans[0] = median(left, right, size);
        for (int i = k; i < n; i++) {
            add(nums[i], left, right, size);
            remove(nums[i - k], left, right, size);
            ans[i - k + 1] = median(left, right, size);
        }
        return ans;
    }

    private static void add(int v, TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (size[0] == 0 || v <= left.lastKey()) {
            insert(left, v);
            size[0]++;
        } else {
            insert(right, v);
            size[1]++;
        }
        rebalance(left, right, size);
    }

    private static void remove(int v, TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (v <= left.lastKey()) {
            erase(left, v);
            size[0]--;
        } else {
            erase(right, v);
            size[1]--;
        }
        rebalance(left, right, size);
    }

    private static void rebalance(TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        if (size[0] > size[1] + 1) {
            int v = left.lastKey();
            erase(left, v);
            size[0]--;
            insert(right, v);
            size[1]++;
        } else if (size[0] < size[1]) {
            int v = right.firstKey();
            erase(right, v);
            size[1]--;
            insert(left, v);
            size[0]++;
        }
    }

    private static double median(TreeMap<Integer, Integer> left, TreeMap<Integer, Integer> right, int[] size) {
        int total = size[0] + size[1];
        if ((total & 1) == 1) {
            return left.lastKey();
        }
        return ((double) left.lastKey() + right.firstKey()) / 2.0;
    }

    private static void insert(TreeMap<Integer, Integer> m, int v) {
        m.merge(v, 1, Integer::sum);
    }

    private static void erase(TreeMap<Integer, Integer> m, int v) {
        int c = m.get(v) - 1;
        if (c == 0) {
            m.remove(v);
        } else {
            m.put(v, c);
        }
    }
}
