class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int[][] result = new int[rows * cols][2];
        int idx = 0;
        result[idx++] = new int[]{rStart, cStart};

        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};
        int d = 0;
        int len = 0;
        int r = rStart, c = cStart;

        while (idx < rows * cols) {
            if (d == 0 || d == 2) {
                len++;
            }
            for (int i = 0; i < len; i++) {
                r += dr[d];
                c += dc[d];
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    result[idx][0] = r;
                    result[idx][1] = c;
                    idx++;
                }
            }
            d = (d + 1) % 4;
        }
        return result;
    }
}
