```java
import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // distinct letters in target, in order of first appearance
        int[] posLetter = new int[n];       // position -> compact letter index
        int[] letterMask = new int[26];     // compact index -> mask of positions? 
        // Hmm, let me do: letterMask indexed by compact index.
        Arrays.fill(letterMask, -1); // temp use
        int d = 0;
        int[] masks = new int[26]; // per compact index
        // Actually simpler: map char -> compact index
        int[] charToIdx = new int[26];
        Arrays.fill(charToIdx, -1);
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] == -1) {
                charToIdx[c] = d++;
            }
            posLetter[i] = charToIdx[c];
        }
        int[] lm = new int[d];
        for (int i = 0; i < n; i++) lm[posLetter[i]] |= (1 << i);

        // build compact sticker counts
        List<int[]> list = new ArrayList<>();
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int c = s.charAt(i) - 'a';
                int k = charToIdx[c];
                if (k >= 0) { cnt[k]++; useful = true; }
            }
            if (useful) list.add(cnt);
        }

        // impossibility check
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int[] sc : list) if (sc[k] > 0) { has = true; break; }
            if (!has) return -1;
        }

        // dedupe
        Set<Long> seen = new HashSet<>();
        List<int[]> uniq = new ArrayList<>();
        for (int[] sc : list) {
            long code = 0;
            for (int k = 0; k < d; k++) code |= ((long) sc[k]) << (4 * k);
            if (seen.add(code)) uniq.add(sc);
        }

        // dominance pruning
        List<int[]> kept = new ArrayList<>();
        int m = uniq.size();
        boolean[] removed = new boolean[m];
        for (int i = 0; i < m; i++) {
            if (removed[i]) continue;
            for (int j = 0; j < m; j++) {
                if (i == j || removed[j]) continue;
                if (dominates(uniq.get(j), uniq.get(i))) {
                    removed[i] = true;
                    break;
                }
            }
            if (!removed[i]) kept.add(uniq.get(i));
        }

        // BFS
        int full = (1 << n) - 1;
        int[] dist = new int[1 << n];
        Arrays.fill(dist, -1);
        dist[full] = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(full);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            int base = dist[cur] + 1;
            for (int[] sc : kept) {
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int x = cur & lm[k];
                    int t = Math.min(Integer.bitCount(x), sc[k]);
                    while (t-- > 0) {
                        nm &= ~(x & (-x));
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = base;
                    if (nm == 0) return base;
                    queue.add(nm);
                }
            }
        }
        return -1;
    }

    private boolean dominates(int[] a, int[] b) {
        for (int k = 0; k < a.length; k++) {
            if (a[k] < b[k]) return false;
        }
        return true;
    }
}
```

