```java
import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // Compress distinct letters of target to indices 0..d-1
        int[] charToIdx = new int[26];
        Arrays.fill(charToIdx, -1);
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] == -1) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // Compact sticker counts over target letters only
        List<int[]> raw = new ArrayList<>();
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) { cnt[k]++; useful = true; }
            }
            if (useful) raw.add(cnt);
        }

        // If some target letter is on no sticker, impossible
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int[] sc : raw) {
                if (sc[k] > 0) { has = true; break; }
            }
            if (!has) return -1;
        }

        // Deduplicate stickers by count vector
        Set<Long> seen = new HashSet<>();
        List<int[]> uniq = new ArrayList<>();
        for (int[] sc : raw) {
            long code = 0L;
            for (int k = 0; k < d; k++) code |= (long) sc[k] << (4 * k);
            if (seen.add(code)) uniq.add(sc);
        }

        // Remove dominated stickers
        int m = uniq.size();
        boolean[] removed = new boolean[m];
        List<int[]> kept = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (removed[i]) continue;
            boolean dominated = false;
            int[] a = uniq.get(i);
            for (int j = 0; j < m && !dominated; j++) {
                if (j == i) continue;
                int[] b = uniq.get(j);
                boolean dom = true;
                for (int k = 0; k < d; k++) {
                    if (b[k] < a[k]) { dom = false; break; }
                }
                if (dom) { dominated = true; }
            }
            if (!dominated) kept.add(a);
            else removed[i] = true;
        }

        // BFS over bitmask of uncovered target positions
        int full = (1 << n) - 1;
        int[] dist = new int[1 << n];
        Arrays.fill(dist, -1);
        dist[full] = 0;
        int[] queue = new int[1 << n];
        int head = 0, tail = 0;
        queue[tail++] = full;
        int[][] st = kept.toArray(new int[0][]);
        while (head < tail) {
            int cur = queue[head++];
            int nd = dist[cur] + 1;
            for (int[] sc : st) {
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int x = cur & letterMask[k];
                    int t = Math.min(Integer.bitCount(x), sc[k]);
                    while (t-- > 0) {
                        nm &= ~x;      // clear lowest set bit of x from nm
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = nd;
                    if (nm == 0) return nd;
                    queue[tail++] = nm;
                }
            }
        }
        return -1;
    }
}
