```java
import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // Map each distinct target letter to a compact index 0..d-1
        int[] charToIdx = new int[26];
        Arrays.fill(charToIdx, -1);
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] < 0) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        // letterMask[k]: bitmask of target positions whose letter is k
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // Compact sticker counts over target letters only
        List<int[]> raw = new ArrayList<>();
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) {
                    cnt[k]++;
                    useful = true;
                }
            }
            if (useful) raw.add(cnt);
        }

        // Impossible if some target letter appears on no sticker
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int[] sc : raw) {
                if (sc[k] > 0) { has = true; break; }
            }
            if (!has) return -1;
        }

        // Deduplicate identical stickers
        Set<Long> seen = new HashSet<>();
        List<int[]> uniq = new ArrayList<>();
        for (int[] sc : raw) {
            long code = 0;
            for (int k = 0; k < d; k++) code |= (long) sc[k] << (4 * k);
            if (seen.add(code)) uniq.add(sc);
        }

        // Drop stickers dominated by another sticker
        int m = uniq.size();
        boolean[] dominated = new boolean[m];
        List<int[]> keptList = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (dominated[i]) continue;
            int[] a = uniq.get(i);
            boolean dom = false;
            for (int j = 0; j < m; j++) {
                if (j == i || dominated[j]) continue;
                int[] b = uniq.get(j);
                boolean covers = true;
                for (int k = 0; k < d; k++) {
                    if (b[k] < a[k]) { covers = false; break; }
                }
                if (covers) { dom = true; break; }
            }
            if (dom) dominated[i] = true;
            else keptList.add(a);
        }
        int[][] st = keptList.toArray(new int[0][]);

        // Group stickers by which target letter they contain
        List<int[]>[] byLetter = new ArrayList[d];
        for (int k = 0; k < d; k++) byLetter[k] = new ArrayList<>();
        for (int[] sc : st) {
            for (int k = 0; k < d; k++) {
                if (sc[k] > 0) byLetter[k].add(sc);
            }
        }

        // BFS over bitmasks of uncovered target positions
