```java
import java.util.*;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // Compact the distinct letters of target to indices 0..d-1
        int[] charToIdx = new int[26];
        Arrays.fill(charToIdx, -1);
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] < 0) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // Count only the letters that matter for each sticker
        List<int[]> raw = new ArrayList<>();
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) {
                    cnt[k]++;
                    useful = true;
                }
            }
            if (useful) raw.add(cnt);
        }

        // If some target letter is on no sticker at all -> impossible
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int[] sc : raw) {
                if (sc[k] > 0) { has = true; break; }
            }
            if (!has) return -1;
        }

        // Deduplicate stickers with identical counts
        Set<Long> seen = new HashSet<>();
        List<int[]> uniq = new ArrayList<>();
        for (int[] sc : raw) {
            long code = 0;
            for (int k = 0; k < d; k++) code |= (long) sc[k] << (4 * k);
            if (seen.add(code)) uniq.add(sc);
        }

        // Remove stickers dominated by another sticker
        int m = uniq.size();
        boolean[] dropped = new boolean[m];
        List<int[]> kept = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (dropped[i]) continue;
            int[] a = uniq.get(i);
            boolean dominated = false;
            for (int j = 0; j < m; j++) {
                if (j == i || dropped[j]) continue;
                int[] b = uniq.get(j);
                boolean ge = true;
                for (int k = 0; k < d; k++) {
                    if (b[k] < a[k]) { ge = false; break; }
                }
                if (ge) { dominated = true; break; }
            }
            if (dominated) dropped[i] = true;
            else kept.add(a);
        }

        // Stickers grouped by the target letters they can supply
        @SuppressWarnings("unchecked")
        List<int[]>[] byLetter = new ArrayList[d];
        for (int k = 0; k < d; k++) byLetter[k] = new ArrayList<>();
        for (int[] sc : kept) {
            for (int k = 0; k < d; k++) {
                if (sc[k] > 0) byLetter[k].add(sc);
            }
        }

        // BFS over bitmasks of still-unsatisfied target positions
        int full = (1 << n) - 1;
        int[] dist = new int[1 << n];
        Arrays.fill(dist, -1);
        dist[full] = 0;
        int[] bfs = new int[1 << n];
        int head = 0, tail = 0;
        bfs[tail++] = full;
        while (head < tail) {
            int cur = bfs[head++];
            int nd = dist[cur] + 1;
            int k0 = posLetter[Integer.numberOfTrailingZeros(cur)];
            for (int[] sc : byLetter[k0]) {
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int x = cur & letterMask[k];
                    int t = Math.min(Integer.bitCount(x), sc[k]);
                    while (t-- > 0) {
                        nm &= ~(x & -x);
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = nd;
                    if (nm == 0) return nd;
                    bfs[tail++] = nm;
                }
            }
        }
        return -1;
    }
}
```

