```java
class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        int[] charToIdx = new int[26];
        for (int i = 0; i < 26; i++) charToIdx[i] = -1;
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] < 0) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // compact sticker counts
        int m = 0;
        int[][] raw = new int[stickers.length][];
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) { cnt[k]++; useful = true; }
            }
            if (useful) raw[m++] = cnt;
        }

        // impossibility check
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int i = 0; i < m; i++) if (raw[i][k] > 0) { has = true; break; }
            if (!has) return -1;
        }

        // dedupe by encoded counts
        long[] code = new long[m];
        for (int i = 0; i < m; i++) {
            long c = 0;
            for (int k = 0; k < d; k++) c |= (long) raw[i][k] << (4 * k);
            code[i] = c;
        }
        boolean[] dup = new boolean[m];
        for (int i = 0; i < m; i++) {
            if (dup[i]) continue;
            for (int j = i + 1; j < m; j++) {
                if (!dup[j] && code[j] == code[i]) dup[j] = true;
            }
        }

        // dominance pruning
        boolean[] dropped = new boolean[m];
        for (int i = 0; i < m; i++) {
            if (dup[i] || dropped[i]) continue;
            for (int j = 0; j < m; j++) {
                if (j == i || dup[j] || dropped[j]) continue;
                boolean ge = true;
                for (int k = 0; k < d; k++) {
                    if (raw[j][k] < raw[i][k]) { ge = false; break; }
                }
                if (ge) { dropped[i] = true; break; }
            }
        }
        int numKept = 0;
        for (int i = 0; i < m; i++) if (!dup[i] && !dropped[i]) numKept++;
        int[][] st = new int[numKept][];
        int idx = 0;
        for (int i = 0; i < m; i++) if (!dup[i] && !dropped[i]) st[idx++] = raw[i];

        // group sticker indices by letter
        int[][] byLetter = new int[d][];
        int[] sz = new int[d];
        for (int i = 0; i < numKept; i++)
            for (int k = 0; k < d; k++) if (st[i][k] > 0) sz[k]++;
        for (int k = 0; k < d; k++) byLetter[k] = new int[sz[k]];
        int[] fill = new int[d];
        for (int i = 0; i < numKept; i++)
            for (int k = 0; k < d; k++) if (st[i][k] > 0) byLetter[k][fill[k]++] = i;

        // BFS
        int full = (1 << n) - 1;
        int[] dist = new int[1 << n];
        for (int i = 0; i < (1 << n); i++) dist[i] = -1;
        dist[full] = 0;
        int[] queue = new int[1 << n];
        int head = 0, tail = 0;
        queue[tail++] = full;
        while (head < tail) {
            int cur = queue[head++];
            int nd = dist[cur] + 1;
            int k0 = posLetter[Integer.numberOfTrailingZeros(cur)];
            int[] list = byLetter[k0];
            for (int q = 0; q < list.length; q++) {
                int[] sc = st[list[q]];
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int cnt = sc[k];
                    if (cnt == 0) continue;
                    int x = cur & letterMask[k];
                    int t = Integer.bitCount(x);
                    if (t > cnt) t = cnt;
                    while (t-- > 0) {
                        nm &= ~(x & -x);
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = nd;
                    if (nm == 0) return nd;
                    queue[tail++] = nm;
                }
            }
        }
        return -1;
    }
}
