```java
class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        if (n == 0) return 0;

        // Compact distinct letters of target to indices 0..d-1
        int[] charToIdx = new int[26];
        for (int i = 0; i < 26; i++) charToIdx[i] = -1;
        int[] posLetter = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            int c = target.charAt(i) - 'a';
            if (charToIdx[c] < 0) charToIdx[c] = d++;
            posLetter[i] = charToIdx[c];
        }
        int[] letterMask = new int[d];
        for (int i = 0; i < n; i++) letterMask[posLetter[i]] |= 1 << i;

        // Per-sticker counts of target letters only
        int[][] raw = new int[stickers.length][];
        int m = 0;
        for (String s : stickers) {
            int[] cnt = new int[d];
            boolean useful = false;
            for (int i = 0; i < s.length(); i++) {
                int k = charToIdx[s.charAt(i) - 'a'];
                if (k >= 0) {
                    cnt[k]++;
                    useful = true;
                }
            }
            if (useful) raw[m++] = cnt;
        }

        // Impossible if some target letter is on no sticker
        for (int k = 0; k < d; k++) {
            boolean has = false;
            for (int i = 0; i < m; i++) {
                if (raw[i][k] > 0) { has = true; break; }
            }
            if (!has) return -1;
        }

        // Drop stickers dominated by another sticker (equal counts count as domination,
        // so duplicates collapse to one survivor)
        boolean[] dropped = new boolean[m];
        for (int i = 0; i < m; i++) {
            if (dropped[i]) continue;
            for (int j = 0; j < m; j++) {
                if (j == i || dropped[j]) continue;
                boolean ge = true;
                for (int k = 0; k < d; k++) {
                    if (raw[j][k] < raw[i][k]) { ge = false; break; }
                }
                if (ge) { dropped[i] = true; break; }
            }
        }
        int numKept = 0;
        for (int i = 0; i < m; i++) if (!dropped[i]) numKept++;
        int[][] st = new int[numKept][];
        int idx = 0;
        for (int i = 0; i < m; i++) if (!dropped[i]) st[idx++] = raw[i];

        // For each target letter, indices of kept stickers supplying it
        int[][] byLetter = new int[d][];
        int[] sz = new int[d];
        for (int i = 0; i < numKept; i++) {
            for (int k = 0; k < d; k++) if (st[i][k] > 0) sz[k]++;
        }
        for (int k = 0; k < d; k++) byLetter[k] = new int[sz[k]];
        int[] fp = new int[d];
        for (int i = 0; i < numKept; i++) {
            for (int k = 0; k < d; k++) if (st[i][k] > 0) byLetter[k][fp[k]++] = i;
        }

        // BFS over bitmasks of unsatisfied target positions
        int total = 1 << n;
        int full = total - 1;
        int[] dist = new int[total];
        for (int i = 0; i < total; i++) dist[i] = -1;
        dist[full] = 0;
        int[] queue = new int[total];
        int head = 0, tail = 0;
        queue[tail++] = full;
        while (head < tail) {
            int cur = queue[head++];
            int nd = dist[cur] + 1;
            int k0 = posLetter[Integer.numberOfTrailingZeros(cur)];
            int[] cand = byLetter[k0];
            for (int q = 0; q < cand.length; q++) {
                int[] sc = st[cand[q]];
                int nm = cur;
                for (int k = 0; k < d; k++) {
                    int cap = sc[k];
                    if (cap == 0) continue;
                    int x = cur & letterMask[k];
                    int t = Integer.bitCount(x);
                    if (t > cap) t = cap;
                    while (t-- > 0) {
                        nm &= ~(x & -x);
                        x &= x - 1;
                    }
                }
                if (nm != cur && dist[nm] == -1) {
                    dist[nm] = nd;
                    if (nm == 0) return nd;
                    queue[tail++] = nm;
                }
            }
        }
        return -1;
    }
}
```

