class Solution {
    public boolean isSolvable(String[] words, String result) {
        long[] coeff = new long[26];
        boolean[] leading = new boolean[26];
        boolean[] present = new boolean[26];

        for (String w : words) {
            long p = 1;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'A';
                coeff[c] += p;
                present[c] = true;
                p *= 10;
            }
            if (w.length() > 1) leading[w.charAt(0) - 'A'] = true;
        }
        long p = 1;
        for (int i = result.length() - 1; i >= 0; i--) {
            int c = result.charAt(i) - 'A';
            coeff[c] -= p;
            present[c] = true;
            p *= 10;
        }
        if (result.length() > 1) leading[result.charAt(0) - 'A'] = true;

        // collect
        int n = 0;
        for (int c = 0; c < 26; c++) if (present[c]) n++;
        int[] chars = new int[n];
        long[] coefs = new long[n];
        int idx = 0;
        for (int c = 0; c < 26; c++) if (present[c]) { chars[idx] = c; coefs[idx] = coeff[c]; idx++; }

        // sort by |coef| desc
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Long.compare(Math.abs(coefs[b]), Math.abs(coefs[a])));
        int[] ch2 = new int[n];
        long[] cf2 = new long[n];
        for (int i = 0; i < n; i++) { ch2[i] = chars[order[i]]; cf2[i] = coefs[order[i]]; }

        // suffix bounds
        long[] sufMax = new long[n + 1];
        long[] sufMin = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            sufMax[i] = sufMax[i + 1] + (cf2[i] > 0 ? cf2[i] * 9 : 0);
            sufMin[i] = sufMin[i + 1] + (cf2[i] < 0 ? cf2[i] * 9 : 0);
        }

        boolean[] used = new boolean[10];
        return dfs(ch2, cf2, sufMax, sufMin, leading, used, 0, 0L);
    }

    private boolean dfs(int[] chars, long[] coefs, long[] sufMax, long[] sufMin,
                        boolean[] leading, boolean[] used, int i, long sum) {
        if (i == chars.length) return sum == 0;
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && leading[chars[i]]) continue;
            long s = sum + coefs[i] * d;
            if (s + sufMax[i + 1] < 0 || s + sufMin[i + 1] > 0) continue;
            used[d] = true;
            if (dfs(chars, coefs, sufMax, sufMin, leading, used, i + 1, s)) return true;
            used[d] = false;
        }
        return false;
    }
}
