class Solution {
    public boolean isSolvable(String[] words, String result) {
        long[] coeff = new long[26];
        boolean[] present = new boolean[26];
        boolean[] noZero = new boolean[26];

        for (String w : words) {
            long p = 1;
            for (int i = w.length() - 1; i >= 0; i--) {
                int c = w.charAt(i) - 'A';
                coeff[c] += p;
                present[c] = true;
                p *= 10;
            }
            if (w.length() > 1) {
                noZero[w.charAt(0) - 'A'] = true;
            }
        }

        long p = 1;
        for (int i = result.length() - 1; i >= 0; i--) {
            int c = result.charAt(i) - 'A';
            coeff[c] -= p;
            present[c] = true;
            p *= 10;
        }
        if (result.length() > 1) {
            noZero[result.charAt(0) - 'A'] = true;
        }

        int n = 0;
        for (int c = 0; c < 26; c++) {
            if (present[c]) n++;
        }
        if (n > 10) return false;

        int[] ch = new int[n];
        long[] cf = new long[n];
        boolean[] lead = new boolean[n];
        int idx = 0;
        for (int c = 0; c < 26; c++) {
            if (present[c]) {
                ch[idx] = c;
                cf[idx] = coeff[c];
                lead[idx] = noZero[c];
                idx++;
            }
        }

        for (int i = 1; i < n; i++) {
            int ci = ch[i];
            long fi = cf[i];
            boolean li = lead[i];
            int j = i - 1;
            while (j >= 0 && Math.abs(cf[j]) < Math.abs(fi)) {
                ch[j + 1] = ch[j];
                cf[j + 1] = cf[j];
                lead[j + 1] = lead[j];
                j--;
            }
            ch[j + 1] = ci;
            cf[j + 1] = fi;
            lead[j + 1] = li;
        }

        long[] sufMax = new long[n + 1];
        long[] sufMin = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            long v = cf[i];
            sufMax[i] = sufMax[i + 1] + (v > 0 ? v * 9 : 0);
            sufMin[i] = sufMin[i + 1] + (v < 0 ? v * 9 : 0);
        }

        return dfs(ch, cf, lead, sufMax, sufMin, new boolean[10], 0, 0L);
    }

    private boolean dfs(int[] ch, long[] cf, boolean[] lead, long[] sufMax, long[] sufMin,
                        boolean[] used, int i, long sum) {
        if (i == ch.length) {
            return sum == 0;
        }
        long c = cf[i];
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && lead[i]) continue;
            long s = sum + c * d;
            if (s + sufMax[i + 1] < 0 || s + sufMin[i + 1] > 0) continue;
            used[d] = true;
            if (dfs(ch, cf, lead, sufMax, sufMin, used, i + 1, s)) {
                return true;
            }
            used[d] = false;
        }
        return false;
    }
}
