class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();
        // collapse consecutive '*'
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (p.charAt(i) == '*' && sb.length() > 0 && sb.charAt(sb.length() - 1) == '*') continue;
            sb.append(p.charAt(i));
        }
        String pp = sb.toString();
        n = pp.length();

        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        // first row: dp[j] for i=0
        for (int j = 1; j <= n; j++) {
            dp[j] = dp[j-1] && pp.charAt(j-1) == '*';
        }
        for (int i = 1; i <= m; i++) {
            boolean[] ndp = new boolean[n + 1];
            for (int j = 1; j <= n; j++) {
                char pc = pp.charAt(j-1);
                if (pc == '*') {
                    ndp[j] = ndp[j-1] || dp[j];
                } else if (pc == '?' || pc == s.charAt(i-1)) {
                    ndp[j] = dp[j-1];
                }
            }
            dp = ndp;
        }
        return dp[n];
    }
}
```

