            sb.append(c);
        }
        String pp = sb.toString();
        int m = s.length();
        int n = pp.length();

        // dp[j] = whether s[0..i) matches pp[0..j) for the current i (rolling over rows)
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // empty pattern matches empty string

        // Base row: matching empty string with pattern prefix — only leading '*'s can do it
        for (int j = 1; j <= n; j++) {
            dp[j] = dp[j - 1] && pp.charAt(j - 1) == '*';
        }

        for (int i = 1; i <= m; i++) {
            boolean[] ndp = new boolean[n + 1];
            char sc = s.charAt(i - 1);
            for (int j = 1; j <= n; j++) {
                char pc = pp.charAt(j - 1);
                if (pc == '*') {
                    // '*' matches empty sequence (ndp[j-1]) or extends to consume s[i-1] (dp[j])
                    ndp[j] = ndp[j - 1] || dp[j];
                } else if (pc == '?' || pc == sc) {
                    ndp[j] = dp[j - 1];
                }
                // otherwise ndp[j] stays false
            }
            dp = ndp;
        }

        return dp[n];
    }
}
